type ModalStackManagerRegisterData = {
  /**A unique key to identify the modal in the stack */
  modalKey: string;

  /** The key down event listener to attach to the document
   * Used e.g. to listen for Escape key presses to close the modal
   */
  documentEventListener: (event: KeyboardEvent) => void;
};

/**
 * Modals and similar modal behavior components (like Popovers treated as modals) might need to handle key events on the document level.
 * E.g to register for Escape key presses to close themselves.
 * This manager keeps track of the currently opened modals in a stack manner,
 * so that only a singular (the latest one opened) receives the key events, and other modals below do get triggered.
 */
class ModalStackManager {
  private stack: Array<{
    modalKey: string;
    documentEventListener: (event: KeyboardEvent) => void;
  }> = [];

  private documentHandler = (event: KeyboardEvent) => {
    //A key event happened, forward it to the top modal in the stack
    const topModal = this.stack[this.stack.length - 1];
    if (topModal) {
      topModal.documentEventListener(event);
    }
  };

  /**
   * Register a newly opened modal that should receive key events
   */
  registerNewlyOpenedModal(registerData: ModalStackManagerRegisterData) {
    if (this.stack.length === 0) {
      document.addEventListener("keydown", this.documentHandler, true);
    }

    const existingIndex = this.stack.findIndex((m) => m.modalKey === registerData.modalKey);
    if (existingIndex !== -1) {
      console.log(
        "ModalStackManager: Modal with key already registered, skipping new register: ",
        registerData.modalKey,
      );
      return;
    }

    this.stack.push(registerData);
  }

  /**
   * Unregister a modal that has been closed and should no longer receive key events
   */
  unregisterClosedModal(modalKey: string) {
    const index = this.stack.findIndex((m) => m.modalKey === modalKey);
    if (index !== -1) {
      this.stack.splice(index, 1);
    }
    if (this.stack.length === 0) {
      document.removeEventListener("keydown", this.documentHandler, true);
    }
  }

  /** Check if there is any modal currently open */
  isAnyModalOpen() {
    return this.stack.length > 0;
  }

  /** Check if a specific modal is currently open */
  isModalOpen(modalKey: string) {
    return this.stack.some((m) => m.modalKey === modalKey);
  }
}

export const ESCAPE_KEYS = new Set(["Escape", "Esc"]);

export const modalStackManager = new ModalStackManager();
