export const EmptyCart: Story = {
  args: {
    ...Primary.args,
    products: [],
    totalSumInclVat: 0,
  },
  //Test to validate that the cart summary is not shown when cart is empty
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Expect container to not be in the document
    const cartSummaryContainer = canvas.queryByTestId("summary-total");
    expect(cartSummaryContainer).not.toBeInTheDocument();
  },
};

export const CartWithItemsButZeroPrice: Story = {
  args: {
    ...Primary.args,
    totalSumInclVat: 0, //Simulate discount for now
  },
  //Test to validate that the total price section is shown even if total is 0 when there are items in the cart
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Expect container to have to child elements
    const cartSummaryContainer = canvas.getByTestId("summary-total");
    expect(cartSummaryContainer).toBeInTheDocument();
    expect(cartSummaryContainer.children.length).toBe(2);
    //First is label
    expect(cartSummaryContainer.children[0]).toHaveTextContent(corei18n.t("cartSummary").trim());
    //Second is amount
    expect(cartSummaryContainer.children[1]).toHaveTextContent("0 kr");
  },
};
