import { CurrencyHelper, multipleClassNames } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { LabelKey } from "@/core/labels/i18n";
import styles from "./summary-total.module.less";

export type SummaryTotalPropsWithPrice = {
  type: "price";
  /**The total price to show in bold */
  price: number;
  /**If the total is after discounts, this is the original price.
   * Will be used to calculated the "Avdragen rabatt" */
  originalProductSummaryAmount?: number;
};

export type SummaryTotalPropsWithoutPrice = {
  type: "noPrice";
};

export type SummaryTotalProps = {
  /**The label id to show for summary e.g. "Summa" or "Kvar att betala" */
  labelId: LabelKey;
} & (SummaryTotalPropsWithPrice | SummaryTotalPropsWithoutPrice);

export function SummaryTotal({ labelId, ...rest }: SummaryTotalProps) {
  const { t } = useTranslation();

  if (rest.type === "noPrice") {
    return (
      <div className={styles.summaryTotalWrapper}>
        <div className={multipleClassNames(styles.row, styles.summaryTotal, "bold")} data-testid="summary-total">
          <div data-contentful-label-id={labelId}>{t(labelId)}</div>
          <div>—</div>
        </div>
      </div>
    );
  }

  const { price, originalProductSummaryAmount } = rest;

  if (!originalProductSummaryAmount) {
    return (
      <div className={styles.summaryTotalWrapper}>
        <div className={multipleClassNames(styles.row, styles.summaryTotal, "bold")} data-testid="summary-total">
          <div data-contentful-label-id={labelId}>{t(labelId)}</div>
          <div>{CurrencyHelper.formatToSek(price)}</div>
        </div>
      </div>
    );
  }
  const discountedAmount = price - originalProductSummaryAmount;
  return (
    <div className={styles.summaryTotalWrapper}>
      <div className={styles.row}>
        <div data-contentful-label-id="cartSummaryProducts">{t("cartSummaryProducts")}</div>
        <div>{CurrencyHelper.formatToSek(originalProductSummaryAmount)}</div>
      </div>
      <div className={styles.row}>
        <div data-contentful-label-id="cartSummaryDeductedDiscounts">{t("cartSummaryDeductedDiscounts")}</div>
        <div>{CurrencyHelper.formatToSek(discountedAmount)}</div>
      </div>
      <div className={multipleClassNames(styles.row, styles.summaryTotal, "bold")} data-testid="summary-total">
        <div data-contentful-label-id={labelId}>{t(labelId)}</div>
        <div>{CurrencyHelper.formatToSek(price)}</div>
      </div>
    </div>
  );
}
